for f in $(git diff origin/main...HEAD --name-only); do
  git show "origin/main:$f" | grep -oE "'[^']*'" | sed "s/^[[:space:]]*//" | sort | uniq -c | sed 's/^ *//' > /tmp/lo.txt
  grep -oE "'[^']*'" "$f" | sed "s/^[[:space:]]*//" | sort | uniq -c | sed 's/^ *//' > /tmp/ln.txt
  # literals whose count decreased
  join -t' ' -j2 -o '0,1.1,2.1' /dev/null /dev/null 2>/dev/null
  python3 - "$f" <<'EOF'
import sys, subprocess, re, collections
f = sys.argv[1]
old = subprocess.run(['git','show',f'origin/main:{f}'],capture_output=True,text=True).stdout
new = open(f).read()
def lits(s):
    return collections.Counter(re.findall(r"'[^']*'", s))
lo, ln = lits(old), lits(new)
gone = {k: lo[k]-ln.get(k,0) for k in lo if ln.get(k,0) < lo[k]}
added = {k: ln[k]-lo.get(k,0) for k in ln if lo.get(k,0) < ln[k]}
if gone or added:
    print(f'--- {f}')
    for k,v in gone.items(): print(f'  -{v}: {k}')
    for k,v in added.items(): print(f'  +{v}: {k}')
EOF
done 2>/dev/null | head -120

