python3 - <<'EOF'
import subprocess, re, collections
files = subprocess.run(['git','diff','origin/main...HEAD','--name-only'],capture_output=True,text=True).stdout.split()
old_needles = collections.Counter()
new_needles = collections.Counter()
for f in files:
    old = subprocess.run(['git','show',f'origin/main:{f}'],capture_output=True,text=True).stdout
    new = open(f).read()
    # needles = string literal passed to contains(...) on a wait idiom, single line
    for m in re.finditer(r"contains\(\s*\n?\s*('(?:[^'\\]|\\.)*')", old):
        old_needles[m.group(1)] += 1
    # waitUntilContains( 'x'  OR  waitUntilContains(\n 'x' / "x"
    for m in re.finditer(r"waitUntilContains\(\s*\n?\s*('(?:[^'\\]|\\.)*'|\"(?:[^\"\\]|\\.)*\")", new):
        new_needles[m.group(1)] += 1
gone = {k: v for k,v in old_needles.items() if new_needles.get(k,0) < v}
added = {k: v for k,v in new_needles.items() if old_needles.get(k,0) < v}
print("NEEDLES GONE:", len(gone))
for k,v in sorted(gone.items())[:40]: print(' -', v, k)
print("NEEDLES ADDED:", len(added))
for k,v in sorted(added.items())[:40]: print(' +', v, k)
EOF

